#include <stdio.h>

int ds(int n) {
    if (n < 10) {
        return n;
    } else {
        int last = n % 10;
        int rest = n / 10;
        int r = ds(rest);
        return last + r;
    }
}

int main() {
    printf("%d\n", ds(9045));
    return 0;
}

