#include <stdio.h>

int digit_sum(int n) {
    int sum = 0;
    for (; n > 0; n /= 10) {
        sum += n % 10;
    }
    return sum;
}

int main() {
    printf("%d\n", digit_sum(9045));
    return 0;
}
